//! Flattened Layer III Huffman lookup tables translated from `huffman.c`.
//!
//! Table nodes use four-bit maximum lookups, with offsets into the same table
//! for continuation nodes.

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Entry {
    Pointer { offset: u16, bits: u8 },
    Pair { x: u8, y: u8, len: u8 },
    Quad { values: [u8; 4], len: u8 },
}

const fn ptr(offset: u16, bits: u8) -> Entry {
    Entry::Pointer { offset, bits }
}
const fn pair(x: u8, y: u8, len: u8) -> Entry {
    Entry::Pair { x, y, len }
}
const fn quad(v: u8, w: u8, x: u8, y: u8, len: u8) -> Entry {
    Entry::Quad {
        values: [v, w, x, y],
        len,
    }
}

